/-- The compact branch scalar equation. Given [the displayed inputs and assumptions](hyp:β,n,σ,τ), [this definition specifies the stated object](goal). -/
def CompactEquation (β : ℝ) (n : ℕ) (σ τ : ℝ) : Prop :=
  2*(2*β+1) * Real.log τ + τ * (1 + Real.log (σ^2 * τ)) = Real.log n + 1

/-- Assumption 8: positive cutoff density and continuous potential means at zero. Given [the displayed inputs and assumptions](hyp:f,mu), [this definition specifies the stated object](goal). -/
def DongA8 (f : ℝ → ℝ) (mu : Bool → ℝ → ℝ) : Prop :=
  0 < f 0 ∧ ∀ d, ContinuousAt (mu d) 0

/-- The exact intermediate-compact branch criterion. Given [the displayed inputs and assumptions](hyp:β,n,σ), [this definition specifies the stated object](goal). -/
def IntermediateCondition (β : ℝ) (n : ℕ) (σ : ℝ) : Prop :=
  Real.log ((n : ℝ) * σ^(4*(2*β+1))) ≤ σ ^ (-2 : ℝ) - 1

/-- The intermediate branch scalar equation. Given [the displayed inputs and assumptions](hyp:β,n,σ,z), [this definition specifies the stated object](goal). -/
def IntermediateEquation (β : ℝ) (n : ℕ) (σ z : ℝ) : Prop :=
  z + (3*(2*β+1)/2) * Real.log z = 1 + Real.log ((n : ℝ) * σ^(2*β+1))

/-- Pei and Shen Assumption 1Y, jointly nondifferential measurement error. Given [the displayed inputs and assumptions](hyp:σ,Q), [this definition specifies the stated object](goal). -/
def PeiShen1Y (σ : ℝ) (Q : GaussianLawData) : Prop :=
  IndepFun (fun ω => σ * errorCoord ω) (fun ω => (score ω, bit (outcome ω))) Q.Q

/-- Pei and Shen Assumption 2C, positive score density on a cutoff neighborhood. Given [the displayed inputs and assumptions](hyp:Q), [this definition specifies the stated object](goal). -/
def PeiShen2C (Q : GaussianLawData) : Prop :=
  ∃ r > 0, ∀ x ∈ Ioo (-r) r, 0 < Q.a x

/-- Pei and Shen Assumption 7, centered Gaussian measurement error. Given [the displayed inputs and assumptions](hyp:σ,Q), [this definition specifies the stated object](goal). -/
def PeiShen7 (σ : ℝ) (Q : GaussianLawData) : Prop :=
  Q.Q.map (fun ω => σ * errorCoord ω) = gaussianReal 0 ⟨σ ^ 2, sq_nonneg σ⟩

/-- Assumption 1Y on the full real-outcome cited domain. Given [the displayed inputs and assumptions](hyp:Q), [this definition specifies the stated object](goal). -/
def PeiShenObserved1Y (Q : Measure PeiShenLatent) : Prop :=
  IndepFun (fun z => z.2.2) (fun z => (z.1, z.2.1)) Q

/-- Assumption 2C requires positivity throughout an open cutoff neighborhood. Given [the displayed inputs and assumptions](hyp:a), [this definition specifies the stated object](goal). -/
def PeiShenObserved2C (a : ℝ → ℝ) : Prop :=
  ∃ r > 0, ∀ x ∈ Ioo (-r) r, 0 < a x

/-- Assumption 7 specifies the actual centered Gaussian measurement error. Given [the displayed inputs and assumptions](hyp:Q,σ), [this definition specifies the stated object](goal). -/
def PeiShenObserved7 (Q : Measure PeiShenLatent) (σ : ℝ) : Prop :=
  Q.map (fun z => z.2.2) = gaussianReal 0 ⟨σ^2, sq_nonneg σ⟩

/-- Extended absolute loss risk retains infinite loss of arbitrary procedures. Given [the displayed inputs and assumptions](hyp:L,σ,n,T), [this definition specifies the stated object](goal). -/
def absRisk (L : LatentLaw) (σ : ℝ) (n : ℕ) (T : Input n → ℝ) : ℝ≥0∞ :=
  ∫⁻ z, ENNReal.ofReal |T z - theta L| ∂experiment L σ n

