/-- Exact public bias moment. Given [the displayed inputs and assumptions](hyp:L,β), [this definition specifies the stated object](goal). -/
def kernelMoment (L : ℕ) (β : ℝ) : ℝ := -- @realizes Moment(endpoint bias moment)
  ∫ x in (0 : ℝ)..1, x ^ β * (endpointKernel L).eval x -- @realizes x(real latent integration argument)

/-- The unnormalized Legendre block before the endpoint taper. Given [the displayed inputs and assumptions](hyp:m,t), [this definition specifies the stated object](goal). -/
def legendreBlockSum (m : ℕ) (t : ℝ) : ℝ :=
  ∑ j ∈ Finset.Icc m (2*m), (2*(j : ℝ)+1) * (-1 : ℝ)^j * legendreP j (2*t-1)

/-- The finite coefficient action of ordinary differentiation. Given [the displayed inputs and assumptions](hyp:m,c,k), [this definition specifies the stated object](goal). -/
def legendreDerivativeAction (m : ℕ) (c : ℕ → ℝ) (k : ℕ) : ℝ :=
  ∑ l ∈ Finset.range (m+1), legendreDerivativeEntry k l * c l

/-- Differentiation in the unnormalized shifted-Legendre basis, retaining parity. Given [the displayed inputs and assumptions](hyp:k,l), [this definition specifies the stated object](goal). -/
def legendreDerivativeEntry (k l : ℕ) : ℝ :=
  if k < l ∧ Odd (l-k) then 2 * (2*(k : ℝ)+1) else 0

/-- Mathlib shifted Legendre uses the reversed interval orientation. Given [the displayed inputs and assumptions](hyp:j,t), [this definition specifies the stated object](goal). -/
def legendreP (j : ℕ) (t : ℝ) : ℝ := -- @realizes Legendre(normalized Mathlib polynomial)
  Polynomial.aeval ((1 - t) / 2) (Polynomial.shiftedLegendre j)

/-- The factorial likelihood tail. Given [the displayed inputs and assumptions](hyp:b,σ,m), [this definition specifies the stated object](goal). -/
def likelihoodTail (b σ : ℝ) (m : ℕ) : ℝ :=
  ∑' j : ℕ, if m-1 ≤ j then likelihoodLambda b σ ^ j / (Nat.factorial j : ℝ) else 0

/-- Signed marked convolution perturbation. Given [the displayed inputs and assumptions](hyp:b,m,σ,w), [this definition specifies the stated object](goal). -/
def markedConvolution (b : ℝ) (m : ℕ) (σ w : ℝ) : ℝ := -- @realizes u(signed marked Gaussian convolution)
  ∫ x in (0 : ℝ)..b, block m (x/b) * phi σ (w - x)

/-- Marked population mean. Given [the displayed inputs and assumptions](hyp:d,L,σ,P,n), [this definition specifies the stated object](goal). -/
def markedMean (d : Bool) (L : ℕ) (σ : ℝ) (P : LatentLaw) (n : ℕ) : ℝ := -- @realizes Amean(marked population expectation)
  ∫ z, markedAvg d L σ z.1 ∂experiment P σ n

/-- Noise-adapted support width. Given [the displayed inputs and assumptions](hyp:σ,m), [this definition specifies the stated object](goal). -/
-- @node: def:noise-support
def noiseSupport (σ : ℝ) (m : ℕ) : ℝ := min 1 (σ * Real.sqrt m / 8) -- @realizes Support(noise-adapted support)

/-- Given [the displayed inputs and assumptions](hyp:d,y), [this definition specifies the stated object](goal). -/
def observedCell (d y : Bool) : Set Obs :=
  {o | o.2.1 = d ∧ o.2.2 = y}

/-- Given [the displayed inputs and assumptions](hyp:L,sigma,d,y), [this definition specifies the stated object](goal). -/
def observedCellMeasure (L : LatentLaw) (sigma : ℝ) (d y : Bool) : Measure ℝ :=
  ((Pobs L sigma).restrict {o | o.2.1 = d ∧ o.2.2 = y}).map Prod.fst

/-- Given the displayed inputs, [this definition specifies the stated object](goal). -/
def observedReference : Measure Obs :=
  volume.prod (Measure.count : Measure (Bool × Bool))

/-- The observed outcome is the potential outcome at the assigned side. Given [the displayed inputs and assumptions](hyp:ω), [this definition specifies the stated object](goal). -/
def outcome (ω : Latent) : Bool := -- @realizes Y(binary consistency map)
  if side ω then ω.2.2.1 else ω.2.1

/-- Source convention: treatment is assigned below the cutoff, Section 2, display (1). Given [the displayed inputs and assumptions](hyp:Q), [this definition specifies the stated object](goal). -/
def peiShenObservedLaw (Q : Measure PeiShenLatent) : Measure (ℝ × Bool × ℝ) :=
  Q.map (fun z => (z.1 + z.2.2, decide (z.1 < 0), z.2.1))

/-- Centered Gaussian density at the public noise scale. Given [the displayed inputs and assumptions](hyp:σ,w), [this definition specifies the stated object](goal). -/
def phi (σ w : ℝ) : ℝ := -- @realizes phi(centered Gaussian density)
  (Real.sqrt (2 * Real.pi * σ ^ 2))⁻¹ * Real.exp (-w ^ 2 / (2 * σ ^ 2))

/-- Clipped upper endpoint. Given [the displayed inputs and assumptions](hyp:β,n,σ,L,z), [this definition specifies the stated object](goal). -/
def polyHi (β : ℝ) (n : ℕ) (σ : ℝ) (L : ℕ) (z : Input n) : ℝ :=
  min 1 (thetaHat L σ z + radius β n σ L)

/-- Clipped lower endpoint. Given [the displayed inputs and assumptions](hyp:β,n,σ,L,z), [this definition specifies the stated object](goal). -/
def polyLo (β : ℝ) (n : ℕ) (σ : ℝ) (L : ℕ) (z : Input n) : ℝ :=
  max (-1) (thetaHat L σ z - radius β n σ L)

/-- Both potential outcomes remain in the latent schedule. Given [the displayed inputs and assumptions](hyp:d,ω), [this definition specifies the stated object](goal). -/
def pot (d : Bool) (ω : Latent) : ℝ := -- @realizes Ypot(binary potential coordinates)
  bit (if d then ω.2.2.1 else ω.2.1)

/-- The public bias-aware radius includes the fallback. Given [the displayed inputs and assumptions](hyp:β,n,σ,L), [this definition specifies the stated object](goal). -/
def radius (β : ℝ) (n : ℕ) (σ : ℝ) (L : ℕ) : ℝ := -- @realizes radius(public radius)
  if L = 0 then 1/2 else 12 * kernelMoment L β + 28 * Real.sqrt (40 * kernelVariance L σ / n)

/-- A supremum construction of the root, whose existence and uniqueness are proof obligations. Given [the displayed inputs and assumptions](hyp:β,n,σ), [this definition specifies the stated object](goal). -/
def rateResolution (β : ℝ) (n : ℕ) (σ : ℝ) : ℝ := -- @realizes Rateresolution(root construction)
  sSup {h ∈ Icc (directResolution β n) 1 |
    Real.log n + (2 * β + 1) * Real.log h - noiseCost h σ ≤ 0}

/-- IID observation law before procedure randomization. Given [the displayed inputs and assumptions](hyp:L,σ,n), [this definition specifies the stated object](goal). -/
def sampleLaw (L : LatentLaw) (σ : ℝ) (n : ℕ) : Measure (Sample n) :=
  Measure.pi (fun _ : Fin n => Pobs L σ) -- @realizes Sample(IID observed law)

