/-- Smallest public minimizer, formed structurally from the finite set. Given [the displayed inputs and assumptions](hyp:β,n,σ), [this definition specifies the stated object](goal). -/
def selectedDegree (β : ℝ) (n : ℕ) (σ : ℝ) : ℕ := -- @realizes Lstar(smallest finite minimizer)
  (minimizingDegrees β n σ).min' (minimizingDegrees_nonempty β n σ)

/-- The observable effect estimate includes the zero-degree fallback. Given [the displayed inputs and assumptions](hyp:L,σ,n,z), [this definition specifies the stated object](goal). -/
def thetaHat (L : ℕ) (σ : ℝ) {n : ℕ} (z : Input n) : ℝ := -- @realizes thetahat(total effect estimate)
  if L = 0 then 0 else armRatio true L σ z.1 - armRatio false L σ z.1

/-- Unmarked treated convolution density. Given [the displayed inputs and assumptions](hyp:σ,w), [this definition specifies the stated object](goal). -/
def treatedConvolution (σ w : ℝ) : ℝ := -- @realizes q(treated Gaussian convolution) @realizes w(real proxy argument)
  ∫ x in (0 : ℝ)..1, phi σ (w - x)

/-- Unmarked population mean. Given [the displayed inputs and assumptions](hyp:d,L,σ,P,n), [this definition specifies the stated object](goal). -/
def unmarkedMean (d : Bool) (L : ℕ) (σ : ℝ) (P : LatentLaw) (n : ℕ) : ℝ := -- @realizes Bmean(unmarked population expectation)
  ∫ z, unmarkedAvg d L σ z.1 ∂experiment P σ n

/-- Common observed density of either untreated outcome cell. Given [the displayed inputs and assumptions](hyp:sigma,w), [this definition specifies the stated object](goal). -/
def witnessControlCellConvolution (sigma w : ℝ) : ℝ :=
  (1/4 : ℝ) * ∫ x in (-1 : ℝ)..0, phi sigma (w-x)

/-- Independent conditional Bernoulli potentials and independent Gaussian perturbation. Given [the displayed inputs and assumptions](hyp:p), [this definition specifies the stated object](goal). -/
def witnessMeasure (p : ℝ → ℝ) : Measure Latent :=
  let M := (uniformScore ⊗ₘ Causalean.Mathlib.Probability.bernoulliMarkKernel (fun _ : ℝ => 1/2))
    ⊗ₘ Causalean.Mathlib.Probability.bernoulliMarkKernel (fun z : ℝ × Bool => p z.1)
  (M.prod (gaussianReal 0 1)).map (fun z => (z.1.1.1, z.1.1.2, z.1.2, z.2))
